const http = require('node:http');
const https = require('node:https');
const fetch = globalThis.fetch || ((urlString, options = {}) => new Promise((resolve, reject) => {
  const transport = String(urlString).startsWith('https://') ? https : http;
  const req = transport.request(urlString, {
    method: options.method || 'GET',
    headers: options.headers || {},
  }, (res) => {
    let body = '';
    res.on('data', (chunk) => {
      body += chunk.toString();
    });
    res.on('end', () => {
      resolve({
        ok: (res.statusCode || 0) >= 200 && (res.statusCode || 0) < 300,
        status: res.statusCode || 0,
        text: async () => body,
        json: async () => body ? JSON.parse(body) : {},
      });
    });
  });
  req.on('error', reject);
  if (options.body) {
    req.write(options.body);
  }
  req.end();
}));

const runnerBase = $env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = $env.AUTOMATION_RUNNER_TOKEN;
if (!runnerBase || !String(runnerBase).trim()) throw new Error('AUTOMATION_RUNNER_BASE_URL is not configured');
const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};
const items = Array.isArray($input.first().json.results) ? $input.first().json.results : [];
const weekAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;
const completed = items.filter((item) => item.completed_at && new Date(item.completed_at).getTime() >= weekAgo);
const carryover = items.filter((item) => !item.completed_at);
const reportRelativePath = `sprint-retros/${new Date().toISOString().replace(/[:]/g, '-')}.md`;
const reportContent = [
  '# Sprint Retrospective',
  '',
  `Generated: ${new Date().toISOString()}`,
  `Completed this sprint: ${completed.length}`,
  `Carryover: ${carryover.length}`,
  '',
  '## Completed',
  '',
  ...(completed.length > 0 ? completed.map((item) => `- ${item.name} [priority=${item.priority || 'none'}]`) : ['- None']),
  '',
  '## Carryover',
  '',
  ...(carryover.length > 0 ? carryover.slice(0, 20).map((item) => `- ${item.name} [priority=${item.priority || 'none'}]`) : ['- None']),
].join('\n');
const writeResponse = await fetch(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: reportContent }),
});
if (!writeResponse.ok) throw new Error(`reports/write failed: ${writeResponse.status}`);
return [{ json: { completedCount: completed.length, carryoverCount: carryover.length, reportRelativePath } }];
